#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Family {
    Towne,
    Dwelling,
    Castle,
    Keep,
}

impl Family {
    fn from_scene(scene: u8) -> Option<Self> {
        if scene == 0 || scene > 32 {
            return None;
        }
        match (scene - 1) >> 3 {
            0 => Some(Self::Towne),
            1 => Some(Self::Dwelling),
            2 => Some(Self::Castle),
            3 => Some(Self::Keep),
            _ => None,
        }
    }

    fn stem(self) -> &'static str {
        match self {
            Self::Towne => "TOWNE",
            Self::Dwelling => "DWELLING",
            Self::Castle => "CASTLE",
            Self::Keep => "KEEP",
        }
    }

    fn from_stem(stem: &str) -> Option<Self> {
        match stem.to_ascii_uppercase().as_str() {
            "TOWNE" | "TOWN" => Some(Self::Towne),
            "DWELLING" => Some(Self::Dwelling),
            "CASTLE" => Some(Self::Castle),
            "KEEP" => Some(Self::Keep),
            _ => None,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Scene {
    byte: u8,
    family: Family,
    block: usize,
}

impl Scene {
    fn new(byte: u8) -> io::Result<Self> {
        let family = Family::from_scene(byte).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("invalid scene byte {byte}"),
            )
        })?;
        Ok(Self {
            byte,
            family,
            block: ((byte - 1) & 7) as usize,
        })
    }

    fn key(self) -> String {
        format!("{}:{}", self.family.stem(), self.block)
    }

    fn from_key(value: &str) -> io::Result<Self> {
        if let Some((family, block)) = value.split_once(':') {
            let family = Family::from_stem(family).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("unknown scene family `{family}`"),
                )
            })?;
            let block = block.parse::<u8>().map_err(|err| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("invalid scene block `{block}`: {err}"),
                )
            })?;
            if block > 7 {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("scene block must be 0..7, got {block}"),
                ));
            }
            let byte = match family {
                Family::Towne => 1 + block,
                Family::Dwelling => 9 + block,
                Family::Castle => 17 + block,
                Family::Keep => 25 + block,
            };
            return Self::new(byte);
        }

        let byte = parse_u8_literal(value)?;
        Self::new(byte)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct DungeonScene {
    byte: u8,
    record: usize,
}

impl DungeonScene {
    fn new(byte: u8) -> io::Result<Self> {
        if !(33..=40).contains(&byte) {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("invalid dungeon scene byte {byte}"),
            ));
        }
        Ok(Self {
            byte,
            record: (byte - 33) as usize,
        })
    }

    fn from_record(record: u8) -> io::Result<Self> {
        if record > 7 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("dungeon record must be 0..7, got {record}"),
            ));
        }
        Self::new(33 + record)
    }

    fn key(self) -> String {
        format!("DUNGEON:{}", self.record)
    }

    fn name(self) -> &'static str {
        match self.record {
            0 => "Deceit",
            1 => "Despise",
            2 => "Destard",
            3 => "Wrong",
            4 => "Covetous",
            5 => "Shame",
            6 => "Hythloth",
            7 => "Doom",
            _ => "Unknown",
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PlayTarget {
    Town(Scene),
    Dungeon(DungeonScene),
    World(WorldPlane),
}

impl PlayTarget {
    fn from_key(value: &str) -> io::Result<Self> {
        if let Some(plane) = WorldPlane::from_key(value) {
            return Ok(Self::World(plane));
        }
        if let Some((family, record)) = value.split_once(':') {
            if family.eq_ignore_ascii_case("DUNGEON") || family.eq_ignore_ascii_case("DUNGEONS") {
                let record = record.parse::<u8>().map_err(|err| {
                    io::Error::new(
                        io::ErrorKind::InvalidInput,
                        format!("invalid dungeon record `{record}`: {err}"),
                    )
                })?;
                return Ok(Self::Dungeon(DungeonScene::from_record(record)?));
            }
            return Ok(Self::Town(Scene::from_key(value)?));
        }

        let byte = parse_u8_literal(value)?;
        if byte == 0 {
            Ok(Self::World(WorldPlane::Britannia))
        } else if (1..=32).contains(&byte) {
            Ok(Self::Town(Scene::new(byte)?))
        } else if (33..=40).contains(&byte) {
            Ok(Self::Dungeon(DungeonScene::new(byte)?))
        } else {
            Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("play scene byte must be 1..40, got {byte}"),
            ))
        }
    }

    fn key(self) -> String {
        match self {
            Self::Town(scene) => scene.key(),
            Self::Dungeon(scene) => scene.key(),
            Self::World(plane) => plane.key().to_string(),
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum WorldPlane {
    Britannia,
    Underworld,
}

impl WorldPlane {
    fn from_key(value: &str) -> Option<Self> {
        if value.eq_ignore_ascii_case("UNDERWORLD") || value.eq_ignore_ascii_case("UNDER") {
            Some(Self::Underworld)
        } else if value.eq_ignore_ascii_case("OVERWORLD")
            || value.eq_ignore_ascii_case("BRITANNIA")
            || value.eq_ignore_ascii_case("BRIT")
            || value.eq_ignore_ascii_case("WORLD")
        {
            Some(Self::Britannia)
        } else {
            None
        }
    }

    fn from_save_z(z: u8) -> Self {
        if z == 0 {
            Self::Britannia
        } else {
            Self::Underworld
        }
    }

    fn key(self) -> &'static str {
        match self {
            Self::Britannia => "BRITANNIA",
            Self::Underworld => "UNDERWORLD",
        }
    }

    fn file_name(self) -> &'static str {
        match self {
            Self::Britannia => "BRIT.DAT",
            Self::Underworld => "UNDER.DAT",
        }
    }

    fn save_floor(self) -> i8 {
        match self {
            Self::Britannia => 0,
            Self::Underworld => -1,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ShrineVirtue {
    Honesty,
    Compassion,
    Valor,
    Justice,
    Sacrifice,
    Honor,
    Spirituality,
    Humility,
}

impl ShrineVirtue {
    fn from_key(value: &str) -> Option<Self> {
        let value = match value.split_once(':') {
            Some((prefix, suffix)) if prefix.eq_ignore_ascii_case("SHRINE") => suffix,
            _ => value,
        };
        match value.to_ascii_uppercase().as_str() {
            "HONESTY" => Some(Self::Honesty),
            "COMPASSION" => Some(Self::Compassion),
            "VALOR" | "VALOUR" => Some(Self::Valor),
            "JUSTICE" => Some(Self::Justice),
            "SACRIFICE" => Some(Self::Sacrifice),
            "HONOR" | "HONOUR" => Some(Self::Honor),
            "SPIRITUALITY" => Some(Self::Spirituality),
            "HUMILITY" => Some(Self::Humility),
            _ => None,
        }
    }

    fn index(self) -> usize {
        match self {
            Self::Honesty => 0,
            Self::Compassion => 1,
            Self::Valor => 2,
            Self::Justice => 3,
            Self::Sacrifice => 4,
            Self::Honor => 5,
            Self::Spirituality => 6,
            Self::Humility => 7,
        }
    }

    fn bit(self) -> u8 {
        1 << self.index()
    }

    fn name(self) -> &'static str {
        match self {
            Self::Honesty => "Honesty",
            Self::Compassion => "Compassion",
            Self::Valor => "Valor",
            Self::Justice => "Justice",
            Self::Sacrifice => "Sacrifice",
            Self::Honor => "Honor",
            Self::Spirituality => "Spirituality",
            Self::Humility => "Humility",
        }
    }

    fn mantra(self) -> &'static str {
        match self {
            Self::Honesty => "Ahm",
            Self::Compassion => "Mu",
            Self::Valor => "Ra",
            Self::Justice => "Beh",
            Self::Sacrifice => "Cah",
            Self::Honor => "Summ",
            Self::Spirituality => "Om",
            Self::Humility => "Lum",
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Direction {
    NorthWest,
    North,
    NorthEast,
    West,
    East,
    SouthWest,
    South,
    SouthEast,
}

impl Direction {
    fn delta(self) -> (isize, isize) {
        match self {
            Self::NorthWest => (-1, -1),
            Self::North => (0, -1),
            Self::NorthEast => (1, -1),
            Self::West => (-1, 0),
            Self::East => (1, 0),
            Self::SouthWest => (-1, 1),
            Self::South => (0, 1),
            Self::SouthEast => (1, 1),
        }
    }

    fn from_play_key(key: char) -> Option<Self> {
        match key.to_ascii_lowercase() {
            '7' | 'y' => Some(Self::NorthWest),
            '8' | 'w' => Some(Self::North),
            '9' | 'u' => Some(Self::NorthEast),
            '4' | 'a' => Some(Self::West),
            '6' | 'd' => Some(Self::East),
            '1' | 'b' | 'z' => Some(Self::SouthWest),
            '2' | 's' => Some(Self::South),
            '3' | 'n' | 'c' => Some(Self::SouthEast),
            _ => None,
        }
    }

    fn is_cardinal(self) -> bool {
        matches!(self, Self::North | Self::East | Self::South | Self::West)
    }

    fn opposite_cardinal(self) -> Option<Self> {
        match self {
            Self::North => Some(Self::South),
            Self::East => Some(Self::West),
            Self::South => Some(Self::North),
            Self::West => Some(Self::East),
            _ => None,
        }
    }

    fn turn_left_cardinal(self) -> Option<Self> {
        match self {
            Self::North => Some(Self::West),
            Self::West => Some(Self::South),
            Self::South => Some(Self::East),
            Self::East => Some(Self::North),
            _ => None,
        }
    }

    fn turn_right_cardinal(self) -> Option<Self> {
        match self {
            Self::North => Some(Self::East),
            Self::East => Some(Self::South),
            Self::South => Some(Self::West),
            Self::West => Some(Self::North),
            _ => None,
        }
    }

    fn name(self) -> &'static str {
        match self {
            Self::NorthWest => "Northwest",
            Self::North => "North",
            Self::NorthEast => "Northeast",
            Self::West => "West",
            Self::East => "East",
            Self::SouthWest => "Southwest",
            Self::South => "South",
            Self::SouthEast => "Southeast",
        }
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
enum WindState {
    #[default]
    Calm,
    North,
    South,
    East,
    West,
}

impl WindState {
    fn from_key(value: &str) -> io::Result<Self> {
        match value.trim().to_ascii_lowercase().as_str() {
            "calm" | "none" | "0" => Ok(Self::Calm),
            "north" | "n" => Ok(Self::North),
            "south" | "s" => Ok(Self::South),
            "east" | "e" => Ok(Self::East),
            "west" | "w" => Ok(Self::West),
            _ => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("wind must be calm, north, south, east, or west, got `{value}`"),
            )),
        }
    }

    fn from_save_byte(byte: u8) -> Self {
        // The public spec verifies only the clean seed's 0 byte; use --wind for
        // semantic non-calm test states until the save-byte table is promoted.
        match byte {
            0 => Self::Calm,
            _ => Self::Calm,
        }
    }

    fn direction(self) -> Option<Direction> {
        match self {
            Self::Calm => None,
            Self::North => Some(Direction::North),
            Self::South => Some(Direction::South),
            Self::East => Some(Direction::East),
            Self::West => Some(Direction::West),
        }
    }

    fn name(self) -> &'static str {
        match self {
            Self::Calm => "Calm",
            Self::North => "North",
            Self::South => "South",
            Self::East => "East",
            Self::West => "West",
        }
    }

    fn status_message(self) -> &'static str {
        match self {
            Self::Calm => "Calm Winds",
            Self::North => "North Winds",
            Self::South => "South Winds",
            Self::East => "East Winds",
            Self::West => "West Winds",
        }
    }

    fn rel_hur_next(self) -> Self {
        match self {
            Self::Calm => Self::North,
            Self::North => Self::South,
            Self::South => Self::East,
            Self::East => Self::West,
            Self::West => Self::Calm,
        }
    }
}

