#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct AnimationClock {
    frame: u8,
    moongate_frame: u8,
}

impl AnimationClock {
    fn tick_static_tiles(&mut self) {
        self.frame = self.frame.wrapping_add(1) & 3;
    }

    fn tick_moongate(&mut self) {
        self.moongate_frame = self.moongate_frame.wrapping_add(1) & (MOONGATE_ANIMATION_FRAMES - 1);
    }

    fn resolve_static_tile(self, tile: u8) -> u8 {
        static_tile_animation_family_base(tile).map_or(tile, |base| base + self.frame)
    }

    fn resolve_moongate_tile(self) -> u8 {
        MOONGATE_TILE_BASE + self.moongate_frame
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ActiveObject {
    type_byte: u8,
    tile: u8,
    x: usize,
    y: usize,
    z: i8,
    phase: u8,
    aux1: u8,
    aux3: u8,
}

impl ActiveObject {
    fn empty() -> Self {
        Self {
            type_byte: 0,
            tile: 0,
            x: 0,
            y: 0,
            z: 0,
            phase: 0,
            aux1: 0,
            aux3: 0,
        }
    }

    fn moonstone_pickup(slot_index: usize, x: usize, y: usize, z: i8) -> Self {
        Self {
            type_byte: FIRST_PLAYABLE_MOONSTONE_PICKUP_TILE,
            tile: FIRST_PLAYABLE_MOONSTONE_PICKUP_TILE,
            x,
            y,
            z,
            phase: STEADY_PHASE,
            aux1: slot_index as u8,
            aux3: MOONSTONE_PICKUP_AUX3,
        }
    }

    fn free(&mut self) {
        self.type_byte = 0;
    }

    fn tick_phase(&mut self) -> PhaseTick {
        let low = self.phase & 0x0f;
        if low == STEADY_PHASE {
            PhaseTick::Steady
        } else if low > 0 {
            self.phase = (self.phase & 0xf0) | (low - 1);
            PhaseTick::Countdown
        } else {
            PhaseTick::DecisionPoint
        }
    }

    fn is_player(self) -> bool {
        self.type_byte == PLAYER_TILE
    }

    fn is_player_phantom(self) -> bool {
        self.type_byte == PLAYER_NPC_SENTINEL_TYPE
    }

    fn is_empty(self) -> bool {
        self.type_byte == 0
    }

    fn moonstone_slot_index(self) -> Option<usize> {
        let slot_index = self.aux1 as usize;
        (self.type_byte == FIRST_PLAYABLE_MOONSTONE_PICKUP_TILE
            && self.tile == FIRST_PLAYABLE_MOONSTONE_PICKUP_TILE
            && self.aux3 == MOONSTONE_PICKUP_AUX3
            && slot_index < MOONSTONE_SLOT_COUNT)
            .then_some(slot_index)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PhaseTick {
    Steady,
    Countdown,
    DecisionPoint,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ActiveShipWind {
    None,
    Stalled,
    Drifted,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct GameClock {
    year: u16,
    month: u8,
    day: u8,
    hour: u8,
    minute: u8,
}

impl GameClock {
    fn new(hour: u8, minute: u8) -> io::Result<Self> {
        Self::with_date(
            PLAY_START_YEAR,
            PLAY_START_MONTH,
            PLAY_START_DAY,
            hour,
            minute,
        )
    }

    fn with_date(year: u16, month: u8, day: u8, hour: u8, minute: u8) -> io::Result<Self> {
        if !(1..=13).contains(&month) || !(1..=28).contains(&day) {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("invalid Britannian date year {year}, month {month}, day {day}"),
            ));
        }
        if hour > 23 || minute > 59 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("invalid clock time {hour:02}:{minute:02}"),
            ));
        }
        Ok(Self {
            year,
            month,
            day,
            hour,
            minute,
        })
    }

    fn advance_minutes(&mut self, minutes: u8) {
        let total = self.minute as u16 + minutes as u16;
        self.minute = (total % 60) as u8;
        for _ in 0..(total / 60) {
            self.advance_hour();
        }
    }

    fn display_hour(self) -> u8 {
        match self.hour {
            0 => 12,
            1..=12 => self.hour,
            _ => self.hour - 12,
        }
    }

    fn am_pm_suffix(self) -> &'static str {
        if self.hour < 12 { "A.M." } else { "P.M." }
    }

    fn advance_hour(&mut self) {
        self.hour += 1;
        if self.hour >= 24 {
            self.hour = 0;
            self.advance_day();
        }
    }

    fn advance_day(&mut self) {
        self.day += 1;
        if self.day > 28 {
            self.day = 1;
            self.month += 1;
            if self.month > 13 {
                self.month = 1;
                self.year = self.year.saturating_add(1);
            }
        }
    }
}

impl Default for GameClock {
    fn default() -> Self {
        Self {
            year: PLAY_START_YEAR,
            month: PLAY_START_MONTH,
            day: PLAY_START_DAY,
            hour: PLAY_START_HOUR,
            minute: 0,
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct RuntimeNpc {
    slot: usize,
    type_byte: u8,
    dialog_id: u8,
    schedule: [u8; 16],
    x: usize,
    y: usize,
    z: u8,
    cached_wp: usize,
    active_object: Option<usize>,
    player_phantom: bool,
}

impl RuntimeNpc {
    fn from_slot(slot: &NpcSlot, hour: u8) -> Self {
        let wp = waypoint_for_hour(&slot.schedule, hour);
        Self {
            slot: slot.slot,
            type_byte: slot.type_byte,
            dialog_id: slot.dialog_id,
            schedule: slot.schedule,
            x: slot.schedule[3 + wp] as usize,
            y: slot.schedule[6 + wp] as usize,
            z: slot.schedule[9 + wp],
            cached_wp: wp,
            active_object: None,
            player_phantom: false,
        }
    }

    fn from_player_phantom(x: usize, y: usize, z: u8, hour: u8) -> Self {
        let mut schedule = [0u8; 16];
        for wp in 0..3 {
            schedule[3 + wp] = x as u8;
            schedule[6 + wp] = y as u8;
            schedule[9 + wp] = z;
        }
        let cached_wp = waypoint_for_hour(&schedule, hour);
        Self {
            slot: PLAYER_NPC_SLOT,
            type_byte: PLAYER_NPC_SENTINEL_TYPE,
            dialog_id: PLAYER_NPC_DIALOG_ID,
            schedule,
            x,
            y,
            z,
            cached_wp,
            active_object: None,
            player_phantom: true,
        }
    }

    fn is_player_phantom(&self) -> bool {
        self.player_phantom
    }

    fn sync_player_phantom_floor(&mut self, floor: u8, hour: u8) {
        self.z = floor;
        for wp in 0..3 {
            self.schedule[9 + wp] = floor;
        }
        self.cached_wp = waypoint_for_hour(&self.schedule, hour);
    }

    fn waypoint_position(&self, wp: usize) -> (usize, usize, u8) {
        (
            self.schedule[3 + wp] as usize,
            self.schedule[6 + wp] as usize,
            self.schedule[9 + wp],
        )
    }
}

