fn main() -> io::Result<()> {
    let args = parse_cli_args(env::args().skip(1))?;
    if args.help {
        print!("{CLI_USAGE}");
        return Ok(());
    }
    if args.visual {
        return run_visual_dispatch(args);
    }
    if args.play {
        return run_play_loop(
            &args.game_dir,
            args.play_options,
            args.raster_diagnostics,
            args.raster_depth,
            args.play_script,
        );
    }

    run_report(&args.game_dir)
}

#[cfg(feature = "visual")]
fn run_visual_dispatch(args: CliArgs) -> io::Result<()> {
    visual::run_visual_loop(&args.game_dir, args.play_options, args.raster_depth)
}

#[cfg(not(feature = "visual"))]
fn run_visual_dispatch(_args: CliArgs) -> io::Result<()> {
    Err(io::Error::new(
        io::ErrorKind::Unsupported,
        "--visual requires building with --features visual (e.g. \
         `cargo run --features visual -- --visual <GAME_DIR>`).",
    ))
}

fn run_report(game_dir: &Path) -> io::Result<()> {
    let mut report = String::new();
    report.push_str("# Lord British throne-room verification slice\n\n");
    report.push_str(&format!("Game data: `{}`\n\n", game_dir.display()));
    report.push_str("This executable is a parity harness. It reads original data at runtime but does not embed or emit raw map, dialogue, or asset dumps.\n\n");

    let lb_candidate = Scene::new(0x11)?; // CASTLE:0 by public scene partition.
    let fifth_castle = Scene::new(0x15)?; // CASTLE:4, the disputed public wording.
    let decomp_special = Scene::new(0x1d)?; // Scene identified by private TOWN note.

    let castle_tlk = parse_tlk(&game_dir.join("CASTLE.TLK"))?;
    let keep_tlk = parse_tlk(&game_dir.join("KEEP.TLK"))?;

    let lb_slots = parse_npc_block(&game_dir, lb_candidate, &castle_tlk)?;
    let fifth_slots = parse_npc_block(&game_dir, fifth_castle, &castle_tlk)?;
    let special_slots = parse_npc_block(&game_dir, decomp_special, &keep_tlk)?;

    let lb_names = names(&lb_slots);
    let fifth_names = names(&fifth_slots);
    let special_names = names(&special_slots);

    let lb_has_castle_staff = contains_all(
        &lb_names,
        &[
            "Alistair", "Stephen", "Treanna", "Margaret", "Desiree", "Saduj",
        ],
    );
    let fifth_has_castle_staff = contains_any(&fifth_names, &["Alistair", "Stephen", "Saduj"]);
    let special_is_keep = decomp_special.family == Family::Keep;

    report.push_str("## Scene binding checks\n\n");
    report.push_str(&format!(
        "- Scene `0x{:02X}` resolves by public partition to `{}`.\n",
        lb_candidate.byte,
        lb_candidate.key()
    ));
    report.push_str(&format!(
        "- Scene `0x{:02X}` resolves by public partition to `{}`.\n",
        fifth_castle.byte,
        fifth_castle.key()
    ));
    report.push_str(&format!(
        "- Scene `0x{:02X}` resolves by public partition to `{}`.\n",
        decomp_special.byte,
        decomp_special.key()
    ));
    report.push_str(&format!(
        "- `CASTLE:0` contains Lord-British-castle staff markers: {}.\n",
        pass_fail(lb_has_castle_staff)
    ));
    report.push_str(&format!(
        "- `CASTLE:4` contains those staff markers: {}.\n",
        pass_fail(fifth_has_castle_staff)
    ));
    report.push_str(&format!(
        "- Private-note special scene `0x1D` maps to keep family under the public partition: {}.\n\n",
        pass_fail(special_is_keep)
    ));

    report.push_str("Representative roster names, limited to avoid dialogue or roster dumps:\n\n");
    report.push_str(&format!(
        "- `{}`: {}\n",
        lb_candidate.key(),
        sample_names(&lb_names)
    ));
    report.push_str(&format!(
        "- `{}`: {}\n",
        fifth_castle.key(),
        sample_names(&fifth_names)
    ));
    report.push_str(&format!(
        "- `{}`: {}\n\n",
        decomp_special.key(),
        sample_names(&special_names)
    ));

    let floor0 = load_floor(&game_dir, lb_candidate, 0)?;
    let floor1 = load_floor(&game_dir, lb_candidate, 1)?;
    let stats0 = analyze_map(lb_candidate, 0, &floor0);
    let stats1 = analyze_map(lb_candidate, 1, &floor1);

    report.push_str("## Map/render checks\n\n");
    append_map_stats(&mut report, &stats0);
    append_map_stats(&mut report, &stats1);

    let start = harvest_location_markers(&floor0)
        .spawn_markers
        .first()
        .copied()
        .or_else(|| first_walkable(&floor0, None))
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "no walkable floor-0 start"))?;
    let target = stats0
        .npc_markers
        .first()
        .copied()
        .filter(|target| *target != start)
        .or_else(|| first_distinct_walkable(&floor0, start))
        .or_else(|| first_walkable(&floor0, None))
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "no floor-0 target"))?;
    let path = find_path(&floor0, start, target);

    report.push_str("## Movement/pathfinding checks\n\n");
    report.push_str(&format!(
        "- Movement probe start: ({}, {}), target: ({}, {}).\n",
        start.0, start.1, target.0, target.1
    ));
    match &path {
        Some(steps) => {
            report.push_str(&format!(
                "- Class-derived pathfinding found a path of {} steps: PASS.\n",
                steps.len().saturating_sub(1)
            ));
            let legal = steps.windows(2).all(|w| {
                manhattan(w[0], w[1]) == 1 && is_probe_walkable(floor0[w[1].1 * 32 + w[1].0])
            });
            report.push_str(&format!(
                "- Simulated step-by-step movement over the path: {}.\n",
                pass_fail(legal)
            ));
        }
        None => {
            report.push_str("- Class-derived pathfinding found no path. This is a WARNING, not a hard failure, because exact passability bitmap placement is still open in the public specs.\n");
        }
    }
    report.push_str(&format!(
        "- Door-family tiles detected on tested floors: {}.\n\n",
        stats0.door_count + stats1.door_count
    ));
    match door_probe(&floor1) {
        Some((pos, opened_walkable)) => {
            report.push_str(&format!(
                "- Door interaction smoke probe at ({}, {}) rewrote a door-family cell and produced a walkable result: {}.\n\n",
                pos.0,
                pos.1,
                pass_fail(opened_walkable)
            ));
        }
        None => report.push_str(
            "- Door interaction smoke probe: WARNING, no door-family tile found on floor 1.\n\n",
        ),
    }

    report.push_str("## Schedule/conversation checks\n\n");
    let occupied = lb_slots.iter().filter(|s| s.type_byte != 0).count();
    let named = lb_slots.iter().filter(|s| s.name.is_some()).count();
    report.push_str(&format!(
        "- Occupied `CASTLE:0` roster slots: {occupied}.\n"
    ));
    report.push_str(&format!(
        "- Occupied slots with resolved TLK display names: {named}.\n"
    ));
    report.push_str("- Noon waypoint sample:\n");
    for slot in lb_slots.iter().filter(|s| s.type_byte != 0).take(6) {
        let wp = waypoint_for_hour(&slot.schedule, 12);
        let name = slot.name.as_deref().unwrap_or("(unnamed)");
        report.push_str(&format!(
            "  - slot {} dlg {} `{}` -> waypoint {} at ({}, {}, {}).\n",
            slot.slot,
            slot.dialog_id,
            name,
            wp,
            slot.schedule[3 + wp],
            slot.schedule[6 + wp],
            slot.schedule[9 + wp] as i8
        ));
    }
    if let Some(slot) = lb_slots
        .iter()
        .find(|slot| slot.type_byte != 0 && slot.dialog_id > 1 && slot.name.is_some())
    {
        let fields = castle_tlk
            .get(&(slot.dialog_id as u16))
            .map(|fields| fields.len())
            .unwrap_or(0);
        let keywords = fields.saturating_sub(5) / 2;
        report.push_str(&format!(
            "- Conversation envelope probe: slot {} dlg {} has the five leading TLK fields and {} keyword pairs: {}.\n",
            slot.slot,
            slot.dialog_id,
            keywords,
            pass_fail(fields >= 5)
        ));
    } else {
        report.push_str(
            "- Conversation envelope probe: FAIL, no named dialogue-bearing slot found.\n",
        );
    }
    report.push_str("\n");

    report.push_str("## Findings\n\n");
    report.push_str("- The slice runs end-to-end for file loading, scene partitioning, roster/TLK joins, map analysis, render hashing, schedule sampling, and pathfinding smoke checks.\n");
    report.push_str("- `CASTLE:0`, not the fifth castle slot, is the strongest data-backed public binding for Lord British's castle in this slice.\n");
    report.push_str("- The private TOWN note's `0x1D` special-case label conflicts with the public scene partition and should be treated as an unresolved private-analysis issue until rechecked.\n");
    report.push_str("- The aggregate report keeps its class-derived smoke path; runtime play can also consume an optional clean-room passability bitmap.\n");

    if !lb_has_castle_staff || !special_is_keep {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "required scene binding check failed",
        ));
    }

    fs::create_dir_all("reports")?;
    fs::write(REPORT_PATH, &report)?;
    print!("{report}");
    println!("\nReport written to {REPORT_PATH}");
    Ok(())
}

fn run_play_loop(
    game_dir: &Path,
    options: PlayOptions,
    raster_diagnostics: bool,
    raster_depth: TileGraphicsDepth,
    play_script: Option<Vec<String>>,
) -> io::Result<()> {
    let intro_target = options.target;
    let intro_floor = options.floor;
    let mut state = PlayState::load_scene(game_dir, options)?;
    let tile_atlas = if raster_diagnostics {
        Some(load_tile_atlas(game_dir, raster_depth)?)
    } else {
        None
    };
    println!("Ultima V first-playable slice");
    println!(
        "Scene {} floor/level {}. Town/world move: numpad 1-9 or lowercase wasd/yubn. Dungeon: W/S forward/back, A/D turn. Enter: e. Open: o. Push: p. Hole up: h+hours. Look: l; fountain drink lY/lN or l2Y. View: v. Use: UT/UG/UK/U1-U8. Stats: Z. Ignite: i. Talk: t or TKEYWORD. Climb: k/< />. Board/Xit/Yell sails: B/X/x/Y. Fire: f or f+dir. Cast: C1IL/C1AZ2/C1AN2/C1M2/C1MV2/C1CIM2/C1IS/C1RT/C1AI/C1IW/C1IMX/C1AS/C1LV/C1HR/C1IP6/C1IQW/C1AWY/C1PU/C1DP/C1AG6/C1FGI6/C1GIN6/C1GIS6/C1AEP/C1EIP/C1PRV2/C1AT. Mix: MIL/0x80/1. Order: N12. Top-down save: QY/QN. Dungeon exit prompt: QY/QN. Buffer/typeahead: buffer. Idle animation: . Optional startup wind/gear/transport/raster diagnostics: --wind, --climbing-gear, --transport, --raster-diagnostics, --raster-depth ega|cga. Pass: Space/Enter. Harness quit: q.",
        intro_target.key(),
        intro_floor
    );
    if let Some(commands) = play_script {
        println!("Script mode: {} command(s).", commands.len());
        return run_play_script_commands(&mut state, game_dir, &commands, tile_atlas.as_ref());
    }
    let mut input = String::new();
    let mut queued_input = VecDeque::new();
    loop {
        print_play_frame(&mut state, tile_atlas.as_ref())?;
        let (key, suffix) = if let Some(key) = queued_input.pop_front() {
            (key, String::new())
        } else {
            print!("> ");
            io::stdout().flush()?;
            input.clear();
            if io::stdin().read_line(&mut input)? == 0 {
                break;
            }
            if state.typeahead_buffer_enabled {
                if let Some(keys) = play_input_typeahead_chars(&input) {
                    let mut keys = keys.into_iter();
                    let key = keys.next().expect("typeahead input is non-empty");
                    queued_input.extend(keys);
                    (key, String::new())
                } else if let Some((key, suffix)) = play_input_key_and_suffix(&input) {
                    (key, suffix)
                } else {
                    handle_empty_play_input(&mut state, game_dir)?;
                    continue;
                }
            } else if let Some((key, suffix)) = play_input_key_and_suffix(&input) {
                (key, suffix)
            } else {
                handle_empty_play_input(&mut state, game_dir)?;
                continue;
            }
        };
        if handle_play_key_input(&mut state, key, &suffix, game_dir)? == PlayInputDisposition::Quit
        {
            break;
        }
    }
    Ok(())
}

fn run_play_script_commands(
    state: &mut PlayState,
    game_dir: &Path,
    commands: &[String],
    tile_atlas: Option<&TileAtlas>,
) -> io::Result<()> {
    print_play_script_snapshot(state, tile_atlas)?;
    for (index, command) in commands.iter().enumerate() {
        println!(
            "script[{}]: {}",
            index + 1,
            play_script_command_label(command)
        );
        let disposition = handle_play_script_command(state, command, game_dir)?;
        print_play_script_snapshot(state, tile_atlas)?;
        if disposition == PlayInputDisposition::Quit {
            break;
        }
    }
    Ok(())
}

fn print_play_frame(state: &mut PlayState, tile_atlas: Option<&TileAtlas>) -> io::Result<()> {
    println!();
    println!("{}", state.render_text_frame(5));
    if let Some(atlas) = tile_atlas {
        println!("{}", raster_diagnostic_line(state, 5, atlas)?);
    }
    Ok(())
}

fn print_play_script_snapshot(
    state: &mut PlayState,
    tile_atlas: Option<&TileAtlas>,
) -> io::Result<()> {
    println!("{}", play_script_state_line(state));
    if let Some(atlas) = tile_atlas {
        println!("{}", raster_diagnostic_line(state, 5, atlas)?);
    }
    Ok(())
}

fn raster_diagnostic_line(
    state: &mut PlayState,
    radius: usize,
    atlas: &TileAtlas,
) -> io::Result<String> {
    let Some(viewport) = state.render_top_down_frame(radius, atlas)? else {
        return Ok("Raster viewport: unavailable for dungeon mode.".to_string());
    };
    Ok(format!(
        "Raster viewport: {}x{} px, {}x{} cells, {}, hash {:016x}.",
        viewport.width,
        viewport.height,
        viewport.cells_wide,
        viewport.cells_high,
        viewport.depth.label(),
        hash_palette_indices(&viewport.pixels)
    ))
}

fn play_script_state_line(state: &PlayState) -> String {
    format!(
        "State: {} at ({}, {}), facing {}, turn {}, date Y{} M{} D{} {:02}:{:02}, transport {}, wind {}, typeahead {}, message-bytes {} hash {:016x}.",
        state.current_area_label(),
        state.player.x,
        state.player.y,
        state.player.facing.name(),
        state.turn,
        state.clock.year,
        state.clock.month,
        state.clock.day,
        state.clock.hour,
        state.clock.minute,
        state.player.transport.status_label(),
        state.wind.status_message(),
        state.typeahead_status_label(),
        state.message.len(),
        hash_bytes(state.message.as_bytes())
    )
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PlayInputDisposition {
    Continue,
    Quit,
}

fn handle_play_key_input(
    state: &mut PlayState,
    key: char,
    suffix: &str,
    game_dir: &Path,
) -> io::Result<PlayInputDisposition> {
    if state.resolve_moongate_prompt(key, game_dir)?.is_some() {
        return Ok(PlayInputDisposition::Continue);
    }
    if key == PLAY_IGNORED_INPUT_KEY {
        state.message = match suffix {
            "function" => "Function key ignored.",
            _ => "Input ignored.",
        }
        .to_string();
        return Ok(PlayInputDisposition::Continue);
    }
    if key == PLAY_TYPEAHEAD_TOGGLE_KEY {
        state.toggle_typeahead_buffer();
        return Ok(PlayInputDisposition::Continue);
    }
    if key == 'q' {
        return Ok(PlayInputDisposition::Quit);
    }
    if matches!(state.area, Area::Dungeon { .. }) && key == 'Q' {
        return Ok(state.exit_to_dos_prompt(parse_inline_yes_no(suffix)));
    }
    if key == 'C' && !suffix.is_empty() {
        let turn_before = state.turn;
        let outcome = state.cast_spell_from_suffix(suffix, game_dir)?;
        state.apply_post_turn_effects_after_outcome(turn_before, game_dir, outcome)?;
        return Ok(PlayInputDisposition::Continue);
    }
    if key == 'M' && !suffix.is_empty() {
        if inline_mix_candidate(suffix) {
            state.mix_reagents_from_suffix(suffix);
        } else if state
            .meditate_shrine_from_suffix(suffix, game_dir)?
            .is_none()
        {
            state.mix_reagents_from_suffix(suffix);
        }
        return Ok(PlayInputDisposition::Continue);
    }
    if key == 'N' && !suffix.is_empty() {
        state.new_order_from_suffix(suffix);
        return Ok(PlayInputDisposition::Continue);
    }
    let inline_direction = suffix.chars().find_map(Direction::from_play_key);
    let inline_hours = parse_inline_hours(suffix);
    let inline_drink = parse_inline_yes_no(suffix);
    let inline_party_index = parse_inline_party_index(suffix);
    let inline_use_request = parse_inline_use_request(suffix);
    let inline_talk_keyword = non_empty_talk_keyword(suffix);
    if state.handle_dungeon_key_with_inline(
        key,
        game_dir,
        inline_hours,
        inline_drink,
        inline_party_index,
        inline_use_request,
    )? {
        return Ok(PlayInputDisposition::Continue);
    }
    if matches!(key, 'T' | 't') && inline_talk_keyword.is_some() {
        let turn_before = state.turn;
        let outcome = state.talk_facing_with_game_dir_and_keyword(game_dir, inline_talk_keyword)?;
        state.apply_post_turn_effects_after_outcome(turn_before, game_dir, outcome)?;
        return Ok(PlayInputDisposition::Continue);
    }
    if state.handle_top_down_key_with_inline(
        key,
        game_dir,
        inline_direction,
        inline_hours,
        inline_drink,
        inline_use_request,
    )? {
        return Ok(PlayInputDisposition::Continue);
    }
    if matches!(state.area, Area::Dungeon { .. }) {
        state.advance_visual_tick();
        state.message = "Zzzzzz...".to_string();
        return Ok(PlayInputDisposition::Continue);
    }
    state.message = format!("Unhandled command `{key}`.");
    Ok(PlayInputDisposition::Continue)
}

fn play_input_key_and_suffix(input: &str) -> Option<(char, String)> {
    let input = input.trim_end_matches(|ch| ch == '\r' || ch == '\n');
    if is_typeahead_toggle_token(input) {
        return Some((PLAY_TYPEAHEAD_TOGGLE_KEY, String::new()));
    }
    if let Some(key) = ansi_navigation_key(input) {
        return Some((key, String::new()));
    }
    if ansi_function_key(input).is_some() {
        return Some((PLAY_IGNORED_INPUT_KEY, "function".to_string()));
    }
    if unclassified_escape_sequence(input) {
        return Some((PLAY_IGNORED_INPUT_KEY, "escape".to_string()));
    }
    let mut chars = input.chars();
    chars.next().map(|key| (key, chars.collect()))
}

fn play_input_typeahead_chars(input: &str) -> Option<Vec<char>> {
    let input = input.trim_end_matches(|ch| ch == '\r' || ch == '\n');
    if input.is_empty()
        || is_typeahead_toggle_token(input)
        || ansi_navigation_key(input).is_some()
        || ansi_function_key(input).is_some()
        || unclassified_escape_sequence(input)
    {
        return None;
    }
    let chars = input.chars().collect::<Vec<_>>();
    if chars.len() > 1 && chars.iter().all(|key| is_simple_typeahead_key(*key)) {
        Some(chars)
    } else {
        None
    }
}

fn is_simple_typeahead_key(key: char) -> bool {
    Direction::from_play_key(key).is_some() || matches!(key, '.' | ' ')
}

fn is_typeahead_toggle_token(input: &str) -> bool {
    matches!(
        input.trim().to_ascii_lowercase().as_str(),
        "buffer" | "typeahead" | "typeahead-buffer" | "toggle-buffer"
    )
}

fn ansi_navigation_key(input: &str) -> Option<char> {
    match input {
        "\x1b[A" | "\x1bOA" => Some('8'),
        "\x1b[B" | "\x1bOB" => Some('2'),
        "\x1b[D" | "\x1bOD" => Some('4'),
        "\x1b[C" | "\x1bOC" => Some('6'),
        "\x1b[H" | "\x1bOH" | "\x1b[1~" | "\x1b[7~" => Some('7'),
        "\x1b[5~" => Some('9'),
        "\x1b[F" | "\x1bOF" | "\x1b[4~" | "\x1b[8~" => Some('1'),
        "\x1b[6~" => Some('3'),
        _ => None,
    }
}

fn ansi_function_key(input: &str) -> Option<u8> {
    match input {
        "\x1bOP" | "\x1b[11~" | "\x1b[[A" => Some(1),
        "\x1bOQ" | "\x1b[12~" | "\x1b[[B" => Some(2),
        "\x1bOR" | "\x1b[13~" | "\x1b[[C" => Some(3),
        "\x1bOS" | "\x1b[14~" | "\x1b[[D" => Some(4),
        "\x1b[15~" | "\x1b[[E" => Some(5),
        "\x1b[17~" => Some(6),
        "\x1b[18~" => Some(7),
        "\x1b[19~" => Some(8),
        "\x1b[20~" => Some(9),
        "\x1b[21~" => Some(10),
        _ => None,
    }
}

fn unclassified_escape_sequence(input: &str) -> bool {
    input.starts_with('\x1b')
        && input.chars().nth(1).is_some()
        && ansi_navigation_key(input).is_none()
        && ansi_function_key(input).is_none()
}

fn handle_empty_play_input(state: &mut PlayState, game_dir: &Path) -> io::Result<()> {
    if state.pending_moongate.is_some() {
        state.resolve_moongate_prompt('\n', game_dir)?;
    } else if state
        .resolve_current_dungeon_room_trigger(Some(game_dir))?
        .is_none()
    {
        state.pass_turn_with_game_dir(Some(game_dir))?;
    }
    Ok(())
}

fn handle_play_script_command(
    state: &mut PlayState,
    command: &str,
    game_dir: &Path,
) -> io::Result<PlayInputDisposition> {
    let command = command.trim();
    if is_typeahead_toggle_token(command) {
        return handle_play_key_input(state, PLAY_TYPEAHEAD_TOGGLE_KEY, "", game_dir);
    }
    if matches!(command.to_ascii_lowercase().as_str(), "empty" | "pass") {
        handle_empty_play_input(state, game_dir)?;
        return Ok(PlayInputDisposition::Continue);
    }
    if let Some(count) = play_script_idle_tick_count(command)? {
        for _ in 0..count {
            if handle_play_key_input(state, '.', "", game_dir)? == PlayInputDisposition::Quit {
                return Ok(PlayInputDisposition::Quit);
            }
        }
        return Ok(PlayInputDisposition::Continue);
    }
    if state.typeahead_buffer_enabled {
        if let Some(keys) = play_input_typeahead_chars(command) {
            for key in keys {
                if handle_play_key_input(state, key, "", game_dir)? == PlayInputDisposition::Quit {
                    return Ok(PlayInputDisposition::Quit);
                }
            }
            return Ok(PlayInputDisposition::Continue);
        }
    }
    let Some((key, suffix)) = play_input_key_and_suffix(command) else {
        handle_empty_play_input(state, game_dir)?;
        return Ok(PlayInputDisposition::Continue);
    };
    handle_play_key_input(state, key, &suffix, game_dir)
}

fn play_script_idle_tick_count(command: &str) -> io::Result<Option<usize>> {
    let command = command.trim();
    let lower = command.to_ascii_lowercase();
    if matches!(lower.as_str(), "idle" | "tick" | "ticks") {
        return Ok(Some(1));
    }
    let Some(value) = lower
        .strip_prefix("idle:")
        .or_else(|| lower.strip_prefix("tick:"))
    else {
        return Ok(None);
    };
    let count = value.parse::<usize>().map_err(|err| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("script idle command `{command}` has invalid tick count: {err}"),
        )
    })?;
    if count == 0 || count > PLAY_SCRIPT_MAX_IDLE_TICKS {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "script idle command `{command}` tick count must be 1..{PLAY_SCRIPT_MAX_IDLE_TICKS}"
            ),
        ));
    }
    Ok(Some(count))
}

fn split_play_script(script: &str) -> Vec<String> {
    script
        .split(';')
        .map(str::trim)
        .filter(|command| !command.is_empty())
        .map(str::to_string)
        .collect()
}

fn play_script_command_label(command: &str) -> String {
    if command.is_empty() {
        return "empty".to_string();
    }
    if let Some(function_key) = ansi_function_key(command.trim()) {
        return format!("F{function_key}");
    }
    let mut label = String::new();
    for ch in command.chars() {
        if ch.is_control() {
            label.push_str(&format!("\\x{:02x}", ch as u32));
        } else {
            label.push(ch);
        }
    }
    label
}

fn parse_cli_args<I>(args: I) -> io::Result<CliArgs>
where
    I: IntoIterator,
    I::Item: Into<String>,
{
    let mut play = false;
    let mut visual = false;
    let mut raster_diagnostics = false;
    let mut raster_depth = TileGraphicsDepth::Ega16;
    let mut play_script = None;
    let mut game_dir = None;
    let mut options = PlayOptions::default();
    let mut from_save = false;
    let mut from_init = false;
    let mut wind_override = None;
    let mut climbing_gear_override = None;
    let mut pending_vehicle_override = None;
    let mut transport_override = None;
    let mut help = false;
    let mut args = args.into_iter().map(Into::into);
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--help" | "-h" => help = true,
            "--play" => play = true,
            "--visual" => visual = true,
            "--play-script" => {
                play = true;
                let value = args.next().ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "--play-script requires semicolon-separated commands",
                    )
                })?;
                if play_script.replace(split_play_script(&value)).is_some() {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "--play-script may only be supplied once",
                    ));
                }
            }
            "--raster-diagnostics" => raster_diagnostics = true,
            "--raster-depth" => {
                let value = args.next().ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "--raster-depth requires ega or cga",
                    )
                })?;
                raster_depth = TileGraphicsDepth::from_key(&value)?;
            }
            "--from-save" => from_save = true,
            "--from-init" => from_init = true,
            "--scene" => {
                let value = args.next().ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "--scene requires a value")
                })?;
                options.target = PlayTarget::from_key(&value)?;
            }
            "--debug-enter" => {
                let value = args.next().ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "--debug-enter requires a value",
                    )
                })?;
                options.debug_enter = Some(PlayTarget::from_key(&value)?);
            }
            "--floor" => {
                let value = args.next().ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "--floor requires a value")
                })?;
                options.floor = value.parse::<i8>().map_err(|err| {
                    io::Error::new(
                        io::ErrorKind::InvalidInput,
                        format!("invalid floor `{value}`: {err}"),
                    )
                })?;
            }
            "--at" => {
                let value = args.next().ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "--at requires x,y")
                })?;
                options.start = Some(parse_start_arg(&value)?);
            }
            "--time" => {
                let value = args.next().ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "--time requires HH:MM")
                })?;
                options.clock = parse_time_arg(&value)?;
            }
            "--wind" => {
                let value = args.next().ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "--wind requires calm|north|south|east|west",
                    )
                })?;
                wind_override = Some(WindState::from_key(&value)?);
            }
            "--climbing-gear" => {
                let value = args.next().ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "--climbing-gear requires a byte value",
                    )
                })?;
                climbing_gear_override = Some(parse_u8_literal(&value)?);
            }
            "--pending-vehicle" => {
                let value = args.next().ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "--pending-vehicle requires frigate:x,y[,skiffs] or skiff:x,y",
                    )
                })?;
                pending_vehicle_override = Some(parse_pending_vehicle_arg(&value)?);
            }
            "--transport" => {
                let value = args.next().ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "--transport requires foot|horse|ship|skiff|carpet|balloon",
                    )
                })?;
                transport_override = Some(parse_transport_arg(&value)?);
            }
            _ if arg.starts_with("--") => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("unknown option `{arg}`"),
                ));
            }
            _ => game_dir = Some(PathBuf::from(arg)),
        }
    }
    let game_dir = game_dir.unwrap_or_else(|| PathBuf::from(DEFAULT_GAME_DIR));
    if help {
        return Ok(CliArgs {
            play: false,
            visual: false,
            raster_diagnostics: false,
            raster_depth,
            play_script: None,
            game_dir,
            play_options: PlayOptions::default(),
            help: true,
        });
    }
    if from_save && from_init {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "--from-save and --from-init are mutually exclusive",
        ));
    }
    if from_save {
        options = load_play_options_from_save(&game_dir)?;
    } else if from_init {
        options = load_play_options_from_init(&game_dir)?;
    }
    if let Some(wind) = wind_override {
        options.wind = wind;
        if wind == WindState::Calm {
            options.wind_save_byte = 0;
        }
    }
    if let Some(climbing_gear) = climbing_gear_override {
        options.climbing_gear = climbing_gear;
    }
    if let Some(pending_vehicle) = pending_vehicle_override {
        options.pending_vehicle = Some(pending_vehicle);
    }
    if let Some(transport) = transport_override {
        options.transport = transport;
        options.timing_status = TimingStatusTag::for_transport(transport);
    }

    Ok(CliArgs {
        play,
        visual,
        raster_diagnostics,
        raster_depth,
        play_script,
        game_dir,
        play_options: options,
        help: false,
    })
}

const CLI_USAGE: &str = "\
Ultima V verification + first-playable harness (clean-room).

USAGE:
    cargo run -- [OPTIONS] [GAME_DIR]

GAME_DIR defaults to the local clean asset path. With no flags, runs the
Lord British throne-room verification report.

OPTIONS:
    -h, --help                Print this usage and exit.
        --play                Launch the terminal first-playable harness.
        --play-script <CMDS>  Run a semicolon-separated script then exit.
                              Implies --play.
        --scene <KEY>         Start scene, e.g. CASTLE:0 or DUNGEON:0.
        --floor <N>           Start floor/level (signed).
        --at <X,Y>            Start coordinates.
        --time <HH:MM>        Start clock.
        --wind <DIR>          calm|north|south|east|west.
        --transport <KIND>    foot|horse|ship|skiff|carpet|balloon.
        --from-save           Seed play options from SAVED.GAM/SAVED.OOL.
        --from-init           Seed play options from INIT.GAM (debug).
        --raster-diagnostics  Emit per-frame raster diagnostics.
        --raster-depth <D>    ega|cga (default ega).
        --visual              Launch the Bevy top-down visual harness.
                              Requires building with `--features visual`.

SMOKE COMMANDS:
    cargo run -- C:\\Games\\U5-Clean
    cargo run -- --play C:\\Games\\U5-Clean
    cargo run -- --play-script \"z;q\" C:\\Games\\U5-Clean
    cargo run -- --play --scene DUNGEON:0 --floor 0 C:\\Games\\U5-Clean
    cargo run --features visual -- --visual --scene BRITANNIA C:\\Games\\U5-Clean
    cargo run --features visual -- --visual --scene CASTLE:0 --floor 0 C:\\Games\\U5-Clean
";

fn load_play_options_from_save(game_dir: &Path) -> io::Result<PlayOptions> {
    let mut options = load_play_options_from_save_file(game_dir, "SAVED.GAM", "--from-save", true)?;
    refresh_saved_ool_mirrors_for_load(game_dir)?;
    options.save_template_source = SaveTemplateSource::SavedGame;
    Ok(options)
}

fn load_play_options_from_init(game_dir: &Path) -> io::Result<PlayOptions> {
    let mut options = load_play_options_from_save_file(game_dir, "INIT.GAM", "--from-init", false)?;
    options.initial_britannia_overlay = Some(load_init_overlay_objects(game_dir)?);
    options.save_template_source = SaveTemplateSource::InitGame;
    Ok(options)
}

fn load_save_image_template(game_dir: &Path, source: SaveTemplateSource) -> io::Result<Vec<u8>> {
    match source {
        SaveTemplateSource::SavedGame => {
            read_save_image_file(&game_dir.join("SAVED.GAM"), "SAVED.GAM")
        }
        SaveTemplateSource::InitGame => {
            read_save_image_file(&game_dir.join("INIT.GAM"), "INIT.GAM")
        }
        SaveTemplateSource::PreferSavedGame => {
            let saved = game_dir.join("SAVED.GAM");
            if saved.exists() {
                return read_save_image_file(&saved, "SAVED.GAM");
            }
            let init = game_dir.join("INIT.GAM");
            if init.exists() {
                return read_save_image_file(&init, "INIT.GAM");
            }
            Err(io::Error::new(
                io::ErrorKind::NotFound,
                "saving requires an existing SAVED.GAM or INIT.GAM template",
            ))
        }
    }
}

fn read_save_image_file(path: &Path, file_name: &str) -> io::Result<Vec<u8>> {
    let bytes = read(path)?;
    if bytes.len() != SAVED_GAM_LEN {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "{file_name} must be {SAVED_GAM_LEN} bytes, got {}",
                bytes.len()
            ),
        ));
    }
    Ok(bytes)
}

fn load_play_options_from_save_file(
    game_dir: &Path,
    file_name: &str,
    option_name: &str,
    include_active_objects: bool,
) -> io::Result<PlayOptions> {
    let bytes = read(&game_dir.join(file_name))?;
    play_options_from_save_bytes_named(&bytes, file_name, option_name, include_active_objects)
}

#[cfg(test)]
fn play_options_from_save_bytes(bytes: &[u8]) -> io::Result<PlayOptions> {
    play_options_from_save_bytes_named(bytes, "SAVED.GAM", "--from-save", true)
}

fn play_options_from_save_bytes_named(
    bytes: &[u8],
    file_name: &str,
    option_name: &str,
    include_active_objects: bool,
) -> io::Result<PlayOptions> {
    if bytes.len() != SAVED_GAM_LEN {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "{file_name} must be {SAVED_GAM_LEN} bytes, got {}",
                bytes.len()
            ),
        ));
    }
    let _avatar_name_present = saved_game_has_avatar_name(bytes);
    let scene_byte = bytes[SAVE_SCENE_OFFSET];
    if scene_byte > 40 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "{option_name} currently supports overworld, town-family, or stock dungeon scenes only; scene is {scene_byte}"
            ),
        ));
    }
    let z = bytes[SAVE_Z_OFFSET];
    let x = bytes[SAVE_X_OFFSET] as usize;
    let y = bytes[SAVE_Y_OFFSET] as usize;
    let (target, floor) = if scene_byte == 0 {
        if x >= WORLD_SIDE || y >= WORLD_SIDE {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("saved world position must be inside 0..255, got ({x}, {y})"),
            ));
        }
        let plane = WorldPlane::from_save_z(z);
        (PlayTarget::World(plane), plane.save_floor())
    } else if scene_byte <= 32 {
        if x >= 32 || y >= 32 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("saved town position must be inside 0..31, got ({x}, {y})"),
            ));
        }
        (PlayTarget::Town(Scene::new(scene_byte)?), z as i8)
    } else {
        if z > 7 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("saved dungeon level must be inside 0..7, got {z}"),
            ));
        }
        if x >= DUNGEON_SIDE || y >= DUNGEON_SIDE {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("saved dungeon position must be inside 0..7, got ({x}, {y})"),
            ));
        }
        (PlayTarget::Dungeon(DungeonScene::new(scene_byte)?), z as i8)
    };

    let mut spell_charges = [0; SPELL_COUNT];
    spell_charges.copy_from_slice(
        &bytes[SAVE_SPELL_CHARGES_OFFSET..SAVE_SPELL_CHARGES_OFFSET + SPELL_COUNT],
    );
    let moonstone_slots = decode_moonstone_gate_slots(bytes);
    let reagents = decode_reagent_stock(bytes);
    let avatar_stats = decode_avatar_stats(bytes);

    Ok(PlayOptions {
        target,
        floor,
        start: Some((x, y)),
        clock: GameClock::with_date(
            u16_at(bytes, SAVE_YEAR_OFFSET),
            bytes[SAVE_MONTH_OFFSET],
            bytes[SAVE_DAY_OFFSET],
            bytes[SAVE_HOUR_OFFSET],
            bytes[SAVE_MINUTE_OFFSET],
        )?,
        food: u16_at(bytes, SAVE_FOOD_STOCK_OFFSET),
        gold: u16_at(bytes, SAVE_GOLD_STOCK_OFFSET),
        keys: bytes[SAVE_KEY_STOCK_OFFSET],
        gems: bytes[SAVE_GEM_STOCK_OFFSET],
        climbing_gear: DEFAULT_CLIMBING_GEAR,
        party: decode_save_party(bytes),
        spell_charges,
        reagents,
        moonstone_slots,
        shrine_ordained_mask: bytes[SAVE_SHRINE_ORDAINED_MASK_OFFSET],
        shrine_codex_mask: bytes[SAVE_SHRINE_CODEX_MASK_OFFSET],
        shrine_standing: [0; VIRTUE_COUNT],
        avatar_stats,
        torches: bytes[SAVE_TORCH_STOCK_OFFSET],
        torch_counter: bytes[SAVE_TORCH_COUNTER_OFFSET],
        light_spell_counter: bytes[SAVE_LIGHT_SPELL_COUNTER_OFFSET],
        wind: WindState::from_save_byte(bytes[SAVE_WIND_OFFSET]),
        wind_save_byte: bytes[SAVE_WIND_OFFSET],
        timing_status: TimingStatusTag::from_save_byte(bytes[SAVE_TIMING_STATUS_TAG_OFFSET]),
        time_stop_counter: 0,
        active_effect_tag: None,
        active_effect_counter: 0,
        transport: transport_from_save_marker(bytes[SAVE_TRANSPORT_MARKER_OFFSET]),
        pending_vehicle: None,
        initial_britannia_overlay: None,
        debug_enter: None,
        saved_active_objects: if include_active_objects {
            Some(decode_saved_active_objects(bytes)?)
        } else {
            None
        },
        save_template_source: SaveTemplateSource::PreferSavedGame,
    })
}

fn decode_reagent_stock(bytes: &[u8]) -> [u8; REAGENT_COUNT] {
    let mut reagents = [0; REAGENT_COUNT];
    for (save_index, recipe_index) in REAGENT_SAVE_ORDER.iter().copied().enumerate() {
        reagents[recipe_index] = bytes[SAVE_REAGENTS_OFFSET + save_index];
    }
    reagents
}

fn encode_reagent_stock(bytes: &mut [u8], reagents: [u8; REAGENT_COUNT]) {
    for (save_index, recipe_index) in REAGENT_SAVE_ORDER.iter().copied().enumerate() {
        bytes[SAVE_REAGENTS_OFFSET + save_index] = reagents[recipe_index];
    }
}

fn decode_avatar_stats(bytes: &[u8]) -> AvatarStats {
    let avatar_record = SAVE_ROSTER_OFFSET;
    AvatarStats {
        strength: bytes[avatar_record + SAVE_CHARACTER_STR_OFFSET],
        dexterity: bytes[avatar_record + SAVE_CHARACTER_DEX_OFFSET],
        intelligence: bytes[avatar_record + SAVE_CHARACTER_INT_OFFSET],
    }
}

fn decode_save_party(bytes: &[u8]) -> Vec<PartyMember> {
    let party_size = bytes[SAVE_PARTY_SIZE_OFFSET] as usize;
    if !(1..=6).contains(&party_size) {
        return default_party();
    }

    (0..party_size)
        .map(|slot| {
            let record = SAVE_ROSTER_OFFSET + slot * SAVE_CHARACTER_RECORD_LEN;
            let status = bytes[record + SAVE_CHARACTER_STATUS_OFFSET];
            let climb_stat = bytes[record + SAVE_CHARACTER_DEX_OFFSET];
            let mana = bytes[record + SAVE_CHARACTER_MANA_OFFSET];
            let hp = u16_at(bytes, record + SAVE_CHARACTER_HP_OFFSET);
            let max_hp = u16_at(bytes, record + SAVE_CHARACTER_MAX_HP_OFFSET);
            let level = bytes[record + SAVE_CHARACTER_LEVEL_OFFSET];
            PartyMember {
                slot: slot as u8,
                status,
                climb_stat,
                mana,
                hp,
                max_hp,
                level,
            }
        })
        .collect()
}

fn decode_moonstone_gate_slots(bytes: &[u8]) -> [MoonstoneGateSlot; MOONSTONE_SLOT_COUNT] {
    let mut slots = [MoonstoneGateSlot::invalid(); MOONSTONE_SLOT_COUNT];
    for (slot_index, slot) in slots.iter_mut().enumerate() {
        *slot = MoonstoneGateSlot {
            x: bytes[SAVE_MOONSTONE_X_OFFSET + slot_index],
            y: bytes[SAVE_MOONSTONE_Y_OFFSET + slot_index],
            scene: bytes[SAVE_MOONSTONE_SCENE_OFFSET + slot_index],
            z: bytes[SAVE_MOONSTONE_Z_OFFSET + slot_index],
        };
    }
    slots
}

fn saved_game_has_avatar_name(bytes: &[u8]) -> bool {
    bytes
        .get(SAVE_AVATAR_NAME_OFFSET..SAVE_AVATAR_NAME_OFFSET + SAVE_AVATAR_NAME_LEN)
        .is_some_and(|name| name.iter().any(|byte| *byte != 0))
}

fn parse_u8_literal(value: &str) -> io::Result<u8> {
    let trimmed = value.trim();
    let parsed = if let Some(hex) = trimmed
        .strip_prefix("0x")
        .or_else(|| trimmed.strip_prefix("0X"))
    {
        u8::from_str_radix(hex, 16)
    } else {
        trimmed.parse::<u8>()
    };
    parsed.map_err(|err| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("invalid byte literal `{value}`: {err}"),
        )
    })
}

fn parse_i8_literal(value: &str) -> io::Result<i8> {
    value.trim().parse::<i8>().map_err(|err| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("invalid signed byte literal `{value}`: {err}"),
        )
    })
}

fn parse_cardinal_direction(value: &str) -> io::Result<Direction> {
    match value.trim().to_ascii_lowercase().as_str() {
        "north" | "n" => Ok(Direction::North),
        "east" | "e" => Ok(Direction::East),
        "south" | "s" => Ok(Direction::South),
        "west" | "w" => Ok(Direction::West),
        _ => Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("direction must be north, east, south, or west, got `{value}`"),
        )),
    }
}

fn parse_inline_hours(value: &str) -> Option<u8> {
    let digits: String = value.chars().filter(|ch| ch.is_ascii_digit()).collect();
    if digits.is_empty() {
        None
    } else {
        digits.parse::<u8>().ok()
    }
}

fn moonstone_phase_from_inline_number(value: u8) -> Option<usize> {
    (1..=MOONSTONE_SLOT_COUNT as u8)
        .contains(&value)
        .then_some(value as usize - 1)
}

fn parse_inline_use_request(value: &str) -> Option<UseItemRequest> {
    let token = value.chars().find(|ch| !ch.is_whitespace())?;
    match token.to_ascii_uppercase() {
        'T' | 'I' => Some(UseItemRequest::Torch),
        'G' | 'V' => Some(UseItemRequest::Gem),
        'K' | 'J' => Some(UseItemRequest::Key),
        '1'..='8' => token
            .to_digit(10)
            .and_then(|digit| moonstone_phase_from_inline_number(digit as u8))
            .map(UseItemRequest::Moonstone),
        _ => Some(UseItemRequest::Invalid),
    }
}

fn parse_inline_cardinal_direction(value: &str) -> Option<Direction> {
    value.chars().rev().find_map(|ch| match ch {
        '8' => Some(Direction::North),
        '6' => Some(Direction::East),
        '2' => Some(Direction::South),
        '4' => Some(Direction::West),
        _ => None,
    })
}

fn parse_inline_yes_no(value: &str) -> Option<bool> {
    value.chars().find_map(|ch| match ch.to_ascii_lowercase() {
        'y' => Some(true),
        'n' => Some(false),
        _ => None,
    })
}

fn parse_inline_party_index(value: &str) -> Option<usize> {
    value
        .chars()
        .find_map(|ch| ch.to_digit(10))
        .and_then(|digit| usize::try_from(digit).ok())
        .map(|digit| digit.saturating_sub(1))
}

fn parse_inline_target_party_index(value: &str) -> Option<usize> {
    value
        .chars()
        .filter_map(|ch| ch.to_digit(10))
        .nth(1)
        .and_then(|digit| usize::try_from(digit).ok())
        .and_then(|digit| digit.checked_sub(1))
}

fn parse_inline_party_swap(value: &str) -> Option<(usize, usize)> {
    let mut digits = value.chars().filter_map(|ch| ch.to_digit(10));
    let first = digits.next()?;
    let second = digits.next()?;
    if first == 0 || second == 0 {
        return None;
    }
    Some(((first - 1) as usize, (second - 1) as usize))
}

fn parse_inline_gate_phase_index(value: &str) -> Option<usize> {
    value
        .chars()
        .filter_map(|ch| ch.to_digit(10))
        .nth(1)
        .and_then(|digit| usize::try_from(digit).ok())
        .and_then(|digit| {
            (1..=MOONSTONE_SLOT_COUNT)
                .contains(&digit)
                .then_some(digit - 1)
        })
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct InlineMixRequest {
    spell_index: Option<usize>,
    reagent_mask: u8,
    amount: u8,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct InlineShrineRequest {
    mantra: String,
    offering: Option<u8>,
}

fn parse_inline_mix_request(value: &str) -> io::Result<Option<InlineMixRequest>> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return Ok(None);
    }
    let parts: Vec<_> = trimmed
        .split(|ch| matches!(ch, '/' | ':' | ','))
        .map(str::trim)
        .filter(|part| !part.is_empty())
        .collect();
    if parts.len() != 3 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "Mix syntax is M<spell>/<reagent-mask>/<quantity>, for example MIL/0x80/1.",
        ));
    }
    let spell_code = inline_spell_code(parts[0]);
    if spell_code.is_empty() {
        return Ok(None);
    }
    let reagent_mask = parse_u8_literal(parts[1]).map_err(|err| {
        io::Error::new(
            err.kind(),
            format!("invalid mix reagent mask `{}`: {err}", parts[1]),
        )
    })?;
    let amount = parse_u8_literal(parts[2]).map_err(|err| {
        io::Error::new(
            err.kind(),
            format!("invalid mix quantity `{}`: {err}", parts[2]),
        )
    })?;
    Ok(Some(InlineMixRequest {
        spell_index: spell_index_from_code(&spell_code),
        reagent_mask,
        amount,
    }))
}

fn inline_mix_candidate(value: &str) -> bool {
    let parts: Vec<_> = value
        .trim()
        .split(|ch| matches!(ch, '/' | ':' | ','))
        .map(str::trim)
        .filter(|part| !part.is_empty())
        .collect();
    parts.len() == 3 && !inline_spell_code(parts[0]).is_empty()
}

fn parse_inline_shrine_request(value: &str) -> io::Result<Option<InlineShrineRequest>> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return Ok(None);
    }
    let parts: Vec<_> = trimmed
        .split(|ch| matches!(ch, '/' | ':' | ','))
        .map(str::trim)
        .filter(|part| !part.is_empty())
        .collect();
    if parts.is_empty() {
        return Ok(None);
    }
    if parts.len() > 2 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "Shrine syntax is M<mantra> or M<mantra>/<offering-digit>.",
        ));
    }
    let mantra = parts[0].to_string();
    if mantra.is_empty() {
        return Ok(None);
    }
    let offering = if let Some(offering) = parts.get(1) {
        if offering.len() != 1 || !offering.as_bytes()[0].is_ascii_digit() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "Shrine offering must be a digit 0 through 9.",
            ));
        }
        Some(offering.as_bytes()[0] - b'0')
    } else {
        None
    };
    Ok(Some(InlineShrineRequest { mantra, offering }))
}

