    #[test]
    fn sync_player_object_repairs_slot_zero_and_clears_duplicate_player_records() {
        let mut state = world_state(open_world_grid(), 4, 5);
        state.player.transport = TransportState::Carpet {
            type_byte: 184,
            tile: 184,
        };
        state.active_objects[0] = ActiveObject {
            type_byte: 192,
            tile: 192,
            x: 9,
            y: 9,
            z: WorldPlane::Underworld.save_floor(),
            phase: 0x21,
            aux1: 7,
            aux3: 8,
        };
        state.active_objects.push(ActiveObject {
            type_byte: PLAYER_TILE,
            tile: 201,
            x: 1,
            y: 1,
            z: WorldPlane::Underworld.save_floor(),
            phase: 0x66,
            aux1: 0x55,
            aux3: 0x77,
        });

        state.sync_player_object();

        assert_eq!(
            state.active_objects[0],
            ActiveObject {
                type_byte: PLAYER_TILE,
                tile: 184,
                x: 4,
                y: 5,
                z: WorldPlane::Underworld.save_floor(),
                phase: STEADY_PHASE,
                aux1: 0,
                aux3: 0,
            }
        );
        assert_eq!(
            state.active_objects[1],
            ActiveObject {
                type_byte: 0,
                tile: 201,
                x: 1,
                y: 1,
                z: WorldPlane::Underworld.save_floor(),
                phase: 0x66,
                aux1: 0x55,
                aux3: 0x77,
            }
        );
        assert!(state.active_objects[1].is_empty());
    }

