        assert_eq!(
            entries,
            vec![
                WorldGetTileEntry {
                    plane: WorldPlane::Underworld,
                    x: 2,
                    y: 1,
                    replacement_tile: 5,
                    expected_tile: Some(55),
                    grant: None,
                },
                WorldGetTileEntry {
                    plane: WorldPlane::Britannia,
                    x: 3,
                    y: 1,
                    replacement_tile: 5,
                    expected_tile: None,
                    grant: None,
                },
                WorldGetTileEntry {
                    plane: WorldPlane::Britannia,
                    x: 4,
                    y: 1,
                    replacement_tile: 5,
                    expected_tile: None,
                    grant: Some(ObjectPickupGrant {
                        kind: ObjectPickupKind::Gold,
                        amount: 7,
                    }),
                },
                WorldGetTileEntry {
                    plane: WorldPlane::Underworld,
                    x: 5,
                    y: 1,
                    replacement_tile: 5,
                    expected_tile: Some(55),
                    grant: Some(ObjectPickupGrant {
                        kind: ObjectPickupKind::Food,
                        amount: 4,
                    }),
                },
            ]
        );
