    fn active_object_encoder_writes_new_empty_records_as_all_zero() {
        let bytes = encode_active_object_table(&[ActiveObject::empty()]).unwrap();

        assert_eq!(&bytes[..OOL_RECORD_LEN], &[0; OOL_RECORD_LEN]);
    }

